import{c as e,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/ReduceSum%E6%8C%89%E7%AC%AC%E4%B8%80%E4%B8%AA%E7%BB%B4%E5%BA%A6%E8%AE%A1%E7%AE%97%E7%A4%BA%E4%BE%8B.418P15B-.png",d="/assets/ReduceSum%E6%8C%89%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%E7%BB%B4%E5%BA%A6%E8%AE%A1%E7%AE%97%E7%A4%BA%E4%BE%8B.CeGJhwUc.png",A=JSON.parse('{"title":"ReduceSum","description":"","frontmatter":{},"headers":[{"level":1,"title":"ReduceSum","slug":"reducesum"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归约操作/ReduceSum接口/ReduceSum-90.md","filePath":"api/SIMD-API/高阶API/归约操作/ReduceSum接口/ReduceSum-90.md"}'),r={name:"api/SIMD-API/高阶API/归约操作/ReduceSum接口/ReduceSum-90.md"};function p(i,t,o,c,u,h){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="reducesum" tabindex="-1">ReduceSum <a class="header-anchor" href="#reducesum" aria-label="Permalink to &quot;ReduceSum&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>对一个多维向量按照指定的维度进行数据累加。</p><p>定义指定计算的维度（Reduce轴）为R轴，非指定维度（Normal轴）为A轴。如下图所示，对shape为(2, 3)的二维矩阵进行运算，指定在第一维计算数据的累加，输出结果为[5, 7, 9]；指定在第二维计算数据的累加，输出结果为[6, 15]。</p><p><strong>图 1</strong> ReduceSum按第一个维度计算示例<br><img src="'+l+'" alt="" title="ReduceSum按第一个维度计算示例"></p><p><strong>图 2</strong> ReduceSum按最后一个维度计算示例<br><img src="'+d+`" alt="" title="ReduceSum按最后一个维度计算示例"></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T, class pattern, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void ReduceSum(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t srcShape[], bool srcInnerPad)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T, class pattern, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void ReduceSum(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const uint32_t srcShape[], bool srcInnerPad)</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及复杂的数学计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持开发者<strong>通过sharedTmpBuffer入参传入</strong>和<strong>接口框架申请</strong>两种方式。</p><ul><li>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</li><li>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</li></ul><p>通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间；接口框架申请的方式，开发者需要预留临时空间。临时空间大小BufferSize的获取方式如下：通过<a href="./GetReduceSumMaxMinTmpSize.html">GetReduceSumMaxMinTmpSize</a>中提供的接口获取需要预留空间范围的大小。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。不同型号支持的数据类型请参考支持的数据类型。</td></tr><tr><td>pattern</td><td>用于指定ReduceSum计算轴，包括Reduce轴和Normal轴。pattern由与向量维度数量相同的A、R字母组合形成，字母A表示Normal轴，R表示Reduce轴。例如，AR表示对二维向量进行ReduceSum计算：第一维是Normal轴，第二维是Reduce轴，即对第二维进行数据累加的计算。 pattern是定义在AscendC::Pattern::Reduce命名空间下的结构体，其成员变量用户无需关注。 pattern当前只支持取值为AR和RA。</td></tr><tr><td>isReuseSource</td><td>是否允许修改源操作数，默认值为false。如果开发者允许源操作数被改写，可以使能该参数，使能后能够节省部分内存空间。 设置为true，则本接口内部计算时复用src的内存空间，节省内存空间；设置为false，则本接口内部计算时不复用src的内存空间。 isReuseSource的使用样例请参考更多样例。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 用于ReduceSum内部复杂计算时存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考GetReduceSumMaxMinTmpSize。</td></tr><tr><td>srcShape</td><td>输入</td><td>uint32_t类型的数组，表示源操作数的shape信息。该shape的维度必须和模板参数pattern的维度一致，当前只支持二维shape。例如，pattern为AR，该shape维度只能是二维。</td></tr><tr><td>srcInnerPad</td><td>输入</td><td>表示实际需要计算的最内层轴数据是否32Bytes对齐。 Ascend 950PR/Ascend 950DT，该参数预留。接口内由参数srcShape和pattern计算最内层轴数据是否32Bytes对齐。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，当前只支持true。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，当前只支持true。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p><strong>不支持源操作数与目的操作数地址重叠。</strong></p></li><li><p>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</p></li><li><p>内部算法不处理累加计算时的数据溢出，溢出场景不保证接口精度。</p></li><li><p>支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：int32_t、uint32_t、float、int64_t、uint64_t。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：float。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t shape[] = { 2, 8 };</span></span>
<span class="line"><span>constexpr bool isReuse = true;</span></span>
<span class="line"><span>AscendC::ReduceSum&lt;float, AscendC::Pattern::Reduce::AR, isReuse&gt;(dstLocal, srcLocal, tmp, shape, true); // tmp为传入的临时空间大小，shape为srcLocal输入的shape， true表示 地址是否32B对齐</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入输出的数据类型为float</span></span>
<span class="line"><span>输入数据(src): </span></span>
<span class="line"><span>[[ 0.0 4.0 2.0 0.0 -1.0 2.0 -1.0 7.0],</span></span>
<span class="line"><span> [ 0.0 1.0 -9.0 2.0 2.0 2.0 8.0 3.0]]</span></span>
<span class="line"><span>输入pattern：AR</span></span>
<span class="line"><span>输入shape：(2,8)</span></span>
<span class="line"><span>输出数据(dst): [13.0 9.0]</span></span></code></pre></div>`,26)])])}const g=e(r,[["render",p]]);export{A as __pageData,g as default};
